        /* ===== STYLES SPÉCIFIQUES À LA PAGE FAQ ===== */
        
        /* Fil d'Ariane */
        .breadcrumb-nav {
            background-color: #f8f9fa;
            padding: 15px 0;
            border-bottom: 1px solid #e9ecef;
        }
        
        .breadcrumb {
            display: flex;
            list-style: none;
            padding: 0;
            margin: 0;
            flex-wrap: wrap;
        }
        
        .breadcrumb-item {
            display: flex;
            align-items: center;
        }
        
        .breadcrumb-item + .breadcrumb-item::before {
            content: "/";
            padding: 0 10px;
            color: #6c757d;
        }
        
        .breadcrumb-item a {
            color: #2c5aa0;
            text-decoration: none;
            display: flex;
            align-items: center;
            gap: 8px;
            font-size: 0.9rem;
            transition: all 0.3s ease;
        }
        
        .breadcrumb-item a:hover {
            color: #ff6b35;
            text-decoration: underline;
        }
        
        .breadcrumb-item.active {
            color: #6c757d;
            font-size: 0.9rem;
        }
        
        /* Hero FAQ */
        .faq-hero {
            background: linear-gradient(135deg, #2c5aa0 0%, #1a3a6e 100%);
            color: white;
            padding: 100px 0;
            text-align: center;
        }
        
        .faq-hero h1, .faq-hero p {
            color: white;
        }
        
        .faq-hero h1 {
            font-size: 3rem;
            margin-bottom: 20px;
        }
        
        .faq-hero p {
            font-size: 1.2rem;
            max-width: 800px;
            margin: 0 auto 30px;
            opacity: 0.9;
        }
        
        /* Navigation par catégories */
        .faq-categories {
            background: #f8f9fa;
            padding: 30px 0;
            border-bottom: 1px solid #e9ecef;
        }
        
        .category-nav {
            display: flex;
            justify-content: center;
            flex-wrap: wrap;
            gap: 15px;
            padding: 0;
            margin: 0;
            list-style: none;
        }
        
        .category-btn {
            padding: 12px 25px;
            background: white;
            border: 2px solid #e9ecef;
            border-radius: 50px;
            font-weight: 600;
            color: #6c757d;
            cursor: pointer;
            transition: all 0.3s ease;
            display: flex;
            align-items: center;
            gap: 10px;
        }
        
        .category-btn:hover {
            border-color: #2c5aa0;
            color: #2c5aa0;
            transform: translateY(-3px);
        }
        
        .category-btn.active {
            background: #2c5aa0;
            color: white;
            border-color: #2c5aa0;
        }
        
        /* Section FAQ */
        .faq-section {
            padding: 60px 0;
        }
        
        .section-header {
            text-align: center;
            margin-bottom: 50px;
        }
        
        .section-header h2 {
            color: #2c5aa0;
            margin-bottom: 15px;
        }
        
        .section-header p {
            color: #6c757d;
            max-width: 700px;
            margin: 0 auto;
            font-size: 1.1rem;
        }
        
        /* Recherche FAQ */
        .faq-search {
            max-width: 600px;
            margin: 0 auto 40px;
            position: relative;
        }
        
        .search-container {
            position: relative;
        }
        
        .search-input {
            width: 100%;
            padding: 16px 20px 16px 50px;
            border: 2px solid #e9ecef;
            border-radius: 50px;
            font-size: 1rem;
            font-family: 'Open Sans', sans-serif;
            transition: all 0.3s ease;
        }
        
        .search-input:focus {
            outline: none;
            border-color: #2c5aa0;
            box-shadow: 0 0 0 3px rgba(44, 90, 160, 0.1);
        }
        
        .search-icon {
            position: absolute;
            left: 20px;
            top: 50%;
            transform: translateY(-50%);
            color: #6c757d;
            font-size: 1.2rem;
        }
        
        .search-results {
            margin-top: 10px;
            font-size: 0.9rem;
            color: #6c757d;
            text-align: center;
        }
        
        /* Accordéon FAQ */
        .faq-accordion {
            max-width: 900px;
            margin: 0 auto;
        }
        
        .faq-category-section {
            margin-bottom: 50px;
            animation: fadeIn 0.5s ease;
        }
        
        @keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(10px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }
        
        .category-title {
            display: flex;
            align-items: center;
            gap: 15px;
            margin-bottom: 25px;
            padding-bottom: 15px;
            border-bottom: 2px solid #e9ecef;
