    <!-- Scripts JavaScript -->
    <script data-cfasync="false" src="/cdn-cgi/scripts/5c5dd728/cloudflare-static/email-decode.min.js"></script>
    
    <script>
        // ============================================
        // GESTION DE LA FAQ DYNAMIQUE
        // ============================================
        
        document.addEventListener('DOMContentLoaded', function() {
            // Données des questions avec statistiques
            const faqStats = JSON.parse(localStorage.getItem('faqStats')) || {};
            
            // Éléments du DOM
            const categoryBtns = document.querySelectorAll('.category-btn');
            const faqSearch = document.getElementById('faqSearch');
            const searchResults = document.getElementById('searchResults');
            const faqItems = document.querySelectorAll('.faq-item');
            const popularCards = document.querySelectorAll('.popular-card');
            const helpfulBtns = document.querySelectorAll('.helpful-btn[data-helpful]');
            const questionForm = document.getElementById('questionForm');
            const questionText = document.getElementById('questionText');
            const charCount = document.querySelector('.char-count');
            
            // Initialiser les statistiques
            function initializeStats() {
                faqItems.forEach(item => {
                    const id = item.id;
                    if (!faqStats[id]) {
                        faqStats[id] = {
                            views: Math.floor(Math.random() * 500) + 100,
                            helpful: Math.floor(Math.random() * 20) + 80,
                            helpfulCount: 0,
                            notHelpfulCount: 0
                        };
                    }
                });
                localStorage.setItem('faqStats', JSON.stringify(faqStats));
            }
            
            // Gestion des catégories
            categoryBtns.forEach(btn => {
                btn.addEventListener('click', function() {
                    // Mettre à jour les boutons actifs
                    categoryBtns.forEach(b => b.classList.remove('active'));
                    this.classList.add('active');
                    
                    const category = this.dataset.category;
                    filterByCategory(category);
                });
            });
            
            // Filtrer par catégorie
            function filterByCategory(category) {
                const sections = document.querySelectorAll('.faq-category-section');
                
                if (category === 'all') {
                    sections.forEach(section => {
                        section.style.display = 'block';
                        setTimeout(() => {
                            section.style.opacity = '1';
                        }, 10);
                    });
                } else {
                    sections.forEach(section => {
                        if (section.dataset.category === category) {
                            section.style.display = 'block';
                            setTimeout(() => {
                                section.style.opacity = '1';
                            }, 10);
                        } else {
                            section.style.opacity = '0';
                            setTimeout(() => {
                                section.style.display = 'none';
                            }, 300);
                        }
                    });
                }
                
                // Réinitialiser la recherche
                faqSearch.value = '';
                searchResults.textContent = 'Filtrage par catégorie activé';
            }
            
            // Recherche dans la FAQ
            faqSearch.addEventListener('input', function() {
                const searchTerm = this.value.toLowerCase().trim();
                let results = 0;
                
                if (searchTerm.length === 0) {
                    searchResults.textContent = 'Tapez pour rechercher des questions...';
                    resetSearch();
                    return;
                }
                
                faqItems.forEach(item => {
                    const question = item.querySelector('.faq-question').textContent.toLowerCase();
                    const answer = item.querySelector('.answer-content').textContent.toLowerCase();
                    const parentSection = item.closest('.faq-category-section');
                    
                    if (question.includes(searchTerm) || answer.includes(searchTerm)) {
                        item.style.display = 'block';
                        parentSection.style.display = 'block';
                        parentSection.style.opacity = '1';
                        highlightText(item, searchTerm);
                        results++;
                    } else {
                        item.style.display = 'none';
                    }
                });
                
                // Gérer les sections vides
                document.querySelectorAll('.faq-category-section').forEach(section => {
                    const visibleItems = section.querySelectorAll('.faq-item[style="display: block"]');
                    if (visibleItems.length === 0) {
                        section.style.display = 'none';
                    }
                });
                
                searchResults.textContent = `${results} résultat(s) trouvé(s)`;
                searchResults.style.color = results > 0 ? '#28a745' : '#dc3545';
            });
            
            // Surligner le texte de recherche
            function highlightText(item, term) {
                const question = item.querySelector('.faq-question');
                const answer = item.querySelector('.answer-content');
                
                // Nettoyer les surlignages précédents
                question.innerHTML = question.textContent;
                answer.innerHTML = answer.textContent;
                
                if (term.length > 2) {
                    const regex = new RegExp(`(${term})`, 'gi');
                    
                    question.innerHTML = question.textContent.replace(regex, '<mark style="background-color: #ffec99; padding: 2px 4px; border-radius: 2px;">$1</mark>');
                    answer.innerHTML = answer.textContent.replace(regex, '<mark style="background-color: #ffec99; padding: 2px 4px; border-radius: 2px;">$1</mark>');
                }
            }
            
            // Réinitialiser la recherche
            function resetSearch() {
                faqItems.forEach(item => {
                    item.style.display = 'block';
                    // Nettoyer les surlignages
                    const question = item.querySelector('.faq-question');
                    const answer = item.querySelector('.answer-content');
                    question.innerHTML = question.textContent;
                    answer.innerHTML = answer.textContent;
                });
                
                // Afficher toutes les sections
                document.querySelectorAll('.faq-category-section').forEach(section => {
                    section.style.display = 'block';
                    section.style.opacity = '1';
                });
            }
            
            // Gestion de l'accordéon
            faqItems.forEach(item => {
                const question = item.querySelector('.faq-question');
                
                question.addEventListener('click', function() {
                    // Fermer les autres items
                    faqItems.forEach(otherItem => {
                        if (otherItem !== item) {
                            otherItem.classList.remove('active');
                        }
                    });
                    
                    // Basculer l'item actuel
                    item.classList.toggle('active');
                    
                    // Enregistrer la vue
                    const id = item.id;
                    if (faqStats[id]) {
                        faqStats[id].views++;
                        localStorage.setItem('faqStats', JSON.stringify(faqStats));
                        updatePopularCards();
                    }
                    
                    // Faire défiler si nécessaire
                    if (item.classList.contains('active')) {
                        setTimeout(() => {
                            item.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
                        }, 300);
                    }
                });
            });
            
            // Cartes populaires
            popularCards.forEach(card => {
                card.addEventListener('click', function() {
                    const questionId = this.dataset.question;
                    const targetItem = document.getElementById(questionId);
                    
                    if (targetItem) {
                        // Ouvrir la question
                        faqItems.forEach(item => item.classList.remove('active'));
                        targetItem.classList.add('active');
                        
                        // Faire défiler vers la question
                        setTimeout(() => {
                            targetItem.scrollIntoView({ behavior: 'smooth' });
                        }, 100);
                        
                        // Ouvrir la catégorie correspondante
                        const category = targetItem.closest('.faq-category-section').dataset.category;
                        categoryBtns.forEach(btn => {
                            if (btn.dataset.category === category) {
                                btn.click();
                            }
                        });
                    }
                });
            });
            
            // Boutons "Cette réponse vous a-t-elle été utile ?"
            helpfulBtns.forEach(btn => {
                btn.addEventListener('click', function() {
                    const questionId = this.dataset.helpful;
                    
                    if (!this.classList.contains('active')) {
                        // Marquer comme utile
                        this.classList.add('active');
                        this.innerHTML = '<i class="fas fa-thumbs-up"></i> Merci pour votre retour !';
                        
                        // Mettre à jour les statistiques
                        if (faqStats[questionId]) {
                            faqStats[questionId].helpfulCount++;
                            faqStats[questionId].helpful = Math.round(
                                (faqStats[questionId].helpfulCount / (faqStats[questionId].helpfulCount + faqStats[questionId].notHelpfulCount)) * 100
                            );
                            localStorage.setItem('faqStats', JSON.stringify(faqStats));
                            updatePopularCards();
                        }
                        
                        // Désactiver le bouton temporairement
                        this.disabled = true;
                        setTimeout(() => {
                            this.disabled = false;
                        }, 3000);
                    }
                });
            });
            
            // Mettre à jour les cartes populaires
            function updatePopularCards() {
                // Cette fonction pourrait mettre à jour les statistiques affichées
                // basées sur les données de faqStats
            }
            
            // Compteur de caractères pour le formulaire
            questionText.addEventListener('input', function() {
                const length = this.value.length;
                charCount.textContent = `${length}/1000 caractères`;
                
                if (length > 900) {
                    charCount.style.color = '#dc3545';
                } else if (length > 700) {
                    charCount.style.color = '#ffc107';
                } else {
                    charCount.style.color = '#666';
                }
            });
            
            // Gestion du formulaire de question
            questionForm.addEventListener('submit', function(e) {
                e.preventDefault();
                
                const name = document.getElementById('questionName').value;
                const email = document.getElementById('questionEmail').value;
                const category = document.getElementById('questionCategory').value;
                const question = questionText.value;
                
                // Simuler l'envoi
                const questions = JSON.parse(localStorage.getItem('submittedQuestions') || '[]');
                questions.push({
                    name,
                    email,
                    category,
                    question,
                    date: new Date().toISOString(),
                    status: 'pending'
                });
                
                localStorage.setItem('submittedQuestions', JSON.stringify(questions));
                
                // Afficher un message de succès
                showMessage('Votre question a été envoyée ! Nous vous répondrons sous 48h.', 'success');
                
                // Réinitialiser le formulaire
                this.reset();
                charCount.textContent = '0/1000 caractères';
                charCount.style.color = '#666';
            });
            
            // Afficher un message
            function showMessage(text, type = 'info') {
                const message = document.createElement('div');
                message.className = `user-message user-message-${type}`;
                message.innerHTML = `
                    <i class="fas fa-${type === 'success' ? 'check-circle' : 'exclamation-circle'}"></i>
                    ${text}
                `;
                
                document.body.appendChild(message);
                
                setTimeout(() => {
                    message.classList.add('show');
                }, 10);
                
                setTimeout(() => {
                    message.classList.remove('show');
                    setTimeout(() => message.remove(), 300);
                }, 3000);
            }
            
            // Gestion du menu mobile
            const mobileMenuBtn = document.getElementById('mobileMenuBtn');
            const mainNav = document.getElementById('mainNav');
            
            if (mobileMenuBtn) {
                mobileMenuBtn.addEventListener('click', () => {
                    mainNav.classList.toggle('show');
                    mobileMenuBtn.innerHTML = mainNav.classList.contains('show') 
                        ? '<i class="fas fa-times"></i>' 
                        : '<i class="fas fa-bars"></i>';
                });
            }
            
            // Fermer le menu mobile en cliquant sur un lien
            document.querySelectorAll('nav a').forEach(link => {
                link.addEventListener('click', () => {
                    if (mainNav && mainNav.classList.contains('show')) {
                        mainNav.classList.remove('show');
                        mobileMenuBtn.innerHTML = '<i class="fas fa-bars"></i>';
                    }
                });
            });
            
            // Scroll vers les sections
            document.getElementById('scrollToSearch').addEventListener('click', function(e) {
                e.preventDefault();
                document.getElementById('search-faq').scrollIntoView({ behavior: 'smooth' });
                faqSearch.focus();
            });
            
            document.getElementById('scrollToQuestion').addEventListener('click', function(e) {
                e.preventDefault();
                document.getElementById('ask-question').scrollIntoView({ behavior: 'smooth' });
            });

            // Appliquer la section depuis l'URL (?section=...)
            const sectionParam = new URLSearchParams(window.location.search).get('section');
            if (sectionParam) {
                const targetElement = document.getElementById(sectionParam);
                if (targetElement) {
                    targetElement.scrollIntoView({ behavior: 'smooth' });
                }
            }
            
            // Initialiser les statistiques
            initializeStats();
            
            console.log('FAQ dynamique initialisée avec succès !');
        });
    </script>
